-- ============================================================================
-- Seed executions use Yahoo Finance daily closes for their actual 2026 trade dates.
UPDATE trades t
SET execution_price = seed.execution_price,
    settlement_value = t.quantity * seed.execution_price,
    settlement_currency = 'USD',
    fx_rate = 1.00000000,
    executed_at = seed.executed_at::timestamptz
FROM (VALUES
    ('c3000000-0000-0000-0000-000000000001', 271.0100, '2026-01-02 21:00:00+00'),
    ('c3000000-0000-0000-0000-000000000002', 267.2600, '2026-01-05 21:00:00+00'),
