-- ── Historical demo trades ────────────────────────────────────────────────
-- Exactly 29,982 bulk trades across the existing 30 demo accounts, plus 18 curated
-- examples above. All execution prices are Yahoo Finance daily closes (2026-01-02
-- through 2026-10-26) for the matching symbol and trade date.
-- Executions are timestamped at the 16:00 America/New_York close, converted to UTC.
-- The seed is rebuilt only while these accounts have no non-seed trades, so real
-- account activity is never deleted or overwritten.
UPDATE accounts a
SET balance = 10000000.0000
WHERE a.account_id::text LIKE 'd4100000-%'
  AND NOT EXISTS (SELECT 1 FROM trades live WHERE live.account_id::text LIKE 'd4100000-%' AND live.trade_id::text NOT LIKE 'c3100000-%');

DELETE FROM holdings h
WHERE h.account_id::text LIKE 'd4100000-%'
  AND NOT EXISTS (SELECT 1 FROM trades live WHERE live.account_id::text LIKE 'd4100000-%' AND live.trade_id::text NOT LIKE 'c3100000-%');

DELETE FROM trades seed
WHERE seed.trade_id::text LIKE 'c3100000-%'
  AND NOT EXISTS (SELECT 1 FROM trades live WHERE live.account_id::text LIKE 'd4100000-%' AND live.trade_id::text NOT LIKE 'c3100000-%');

