WHERE NOT EXISTS (SELECT 1 FROM trades live WHERE live.account_id::text LIKE 'd4100000-%' AND live.trade_id::text NOT LIKE 'c3100000-%')
ON CONFLICT DO NOTHING;

INSERT INTO trades (trade_id, account_id, instrument_id, side, quantity, execution_price, settlement_value, settlement_currency, fx_rate, executed_at)
SELECT s.trade_id::uuid, s.account_id::uuid, i.instrument_id, s.side, s.quantity,
