) AS s(trade_id, account_id, ticker, side, quantity, execution_price, settlement_value, executed_at)
JOIN instruments i ON i.ticker = s.ticker
WHERE NOT EXISTS (SELECT 1 FROM trades live WHERE live.account_id::text LIKE 'd4100000-%' AND live.trade_id::text NOT LIKE 'c3100000-%')
ON CONFLICT DO NOTHING;

-- Keep seeded cash consistent with generated buys and sells; skip accounts with real trades.
UPDATE accounts a
SET balance = 10000000.0000 - activity.net_spend
FROM (
    SELECT account_id, SUM(CASE side WHEN 'BUY' THEN trade_value ELSE -trade_value END) AS net_spend
    FROM trades
    WHERE trade_id::text LIKE 'c3100000-%'
    GROUP BY account_id
) activity
WHERE a.account_id = activity.account_id
  AND NOT EXISTS (SELECT 1 FROM trades live WHERE live.account_id::text LIKE 'd4100000-%' AND live.trade_id::text NOT LIKE 'c3100000-%');

-- ── Derived holdings ───────────────────────────────────────────────────
-- Aggregated from the trades above rather than written out, so the two can never
-- disagree. Skipped for any account that has traded since seeding: a position sold
-- out through the app would otherwise be resurrected on the next restart.
INSERT INTO holdings (account_id, instrument_id, quantity)
SELECT t.account_id,
       t.instrument_id,
       SUM(CASE t.side WHEN 'BUY' THEN t.quantity ELSE -t.quantity END)
FROM trades t
WHERE t.trade_id::text LIKE 'c3100000-%'
  AND NOT EXISTS (
    SELECT 1 FROM trades live
    WHERE live.account_id = t.account_id
      AND live.trade_id::text NOT LIKE 'c3100000-%'
  )
GROUP BY t.account_id, t.instrument_id
HAVING SUM(CASE t.side WHEN 'BUY' THEN t.quantity ELSE -t.quantity END) > 0
ON CONFLICT (account_id, instrument_id) DO UPDATE
SET quantity = EXCLUDED.quantity;
